	export const splitText = (element) => {
		const text = element.textContent;
		element.innerHTML = '';
		text.split('').forEach((char) => {
			const span = document.createElement('span');
			span.textContent = char === ' ' ? '\u00A0' : char; // Preserve spaces
			element.appendChild(span);
		});
	};


